"""The catalog of every SDK method, generated by introspection."""

from __future__ import annotations

import difflib
import fnmatch
import inspect
import logging
import re
import typing
from dataclasses import dataclass, field
from typing import Any, Callable, Iterable

from fastmcp.tools import Tool
from fastmcp.utilities.types import get_cached_typeadapter
from pydantic import TypeAdapter

from gcore_mcp_server.core.inspection import iter_sdk_methods

from .classify import POLL_SUFFIX, Access, classify
from .docstrings import parse_docstring
from .search import BM25Index, expand_query, normalize_phrases, tokenize
from .returns import describe_returns

from .typed import build_typed_function, scoped_path_params

logger = logging.getLogger(__name__)

# Seen live: a security audit read rules without remote_ip_prefix (null:
# any source) as "not open", because null fields are left out of results.
NULL_NOTE = "Results leave out null fields: a missing key means the value is null."

# SDK attributes that are client plumbing, not API operations.
EXCLUDED_SERVICES = frozenset({"qs", "timeout"})
EXCLUDED_METHODS = frozenset({"with_options", "copy", "as_dict"})


@dataclass
class ToolEntry:
    """One SDK method as the server exposes it."""

    name: str
    """Dotted SDK path, e.g. ``cloud.instances.list``. The canonical tool name."""

    access: Access
    summary: str
    description: str
    method: Callable[..., Any]
    arg_docs: dict[str, str] = field(default_factory=dict[str, str])
    _fn: Callable[..., Any] | None = None
    _string_params: list[str] = field(default_factory=list[str])
    _schema: dict[str, Any] | None = None
    _path_params: frozenset[str] | None = None
    _returns: dict[str, Any] | None = None

    @property
    def group(self) -> str:
        """Resource path, e.g. ``cloud.instances`` for ``cloud.instances.list``."""
        return self.name.rsplit(".", 1)[0]

    @property
    def service(self) -> str:
        return self.name.split(".", 1)[0]

    @property
    def tool_name(self) -> str:
        """Identifier used in direct mode (MCP names may not contain dots)."""
        return self.name.replace(".", "_")

    @property
    def returns(self) -> dict[str, Any] | None:
        """Outline of the result's fields, from the SDK's return type."""
        if self._returns is None:
            outline = describe_returns(self.method)
            if outline is not None and self.searches_all_regions:
                outline["without_region_id"] = (
                    "every region is searched and the pages are merged into "
                    "{count, results, regions_searched, ...}; each item has region_id"
                )
            self._returns = outline or {}
        return self._returns or None

    @property
    def fills_client_id(self) -> bool:
        """The SDK requires ``client_id``; the server fills it in when omitted."""
        try:
            param = inspect.signature(self.method).parameters.get("client_id")
        except (TypeError, ValueError):
            return False
        return param is not None and param.default is inspect.Parameter.empty

    @property
    def searches_all_regions(self) -> bool:
        """A list call that runs in every region when region_id is omitted.

        Mirrors ``runtime.scope.CloudScope``: a read ``list`` whose region is a
        path parameter and which needs no other identifier.
        """
        return (
            self.access is Access.READ
            and self.name.rsplit(".", 1)[-1] == "list"
            and "region_id" in self.path_params
            and not self.required_params
        )

    @property
    def path_params(self) -> frozenset[str]:
        """``project_id``/``region_id`` that are path parameters (see typed.py)."""
        if self._path_params is None:
            self._path_params = scoped_path_params(self.method, self.name)
        return self._path_params

    def _ensure_fn(self) -> None:
        if self._fn is None:
            self._fn, self._string_params = build_typed_function(
                self.method,
                self.name,
                self.arg_docs,
                self.description,
                path_params=self.path_params,
            )

    @property
    def fn(self) -> Callable[..., Any]:
        """Typed async function that validates arguments and calls the SDK."""
        self._ensure_fn()
        assert self._fn is not None
        return self._fn

    @property
    def string_params(self) -> list[str]:
        self._ensure_fn()
        return self._string_params

    @property
    def adapter(self) -> TypeAdapter[Any]:
        return get_cached_typeadapter(self.fn)

    @property
    def input_schema(self) -> dict[str, Any]:
        """JSON schema of the arguments, exactly as FastMCP would advertise it."""
        if self._schema is None:
            tool = Tool.from_function(self.fn, name=self.tool_name)
            schema: dict[str, Any] = compact_schema(tool.parameters)
            self._schema = schema
            return schema
        return self._schema

    @property
    def required_params(self) -> list[str]:
        return list(self.input_schema.get("required", []))

    @property
    def param_names(self) -> list[str]:
        return list(self.input_schema.get("properties", {}).keys())


def compact_schema(schema: Any) -> Any:
    """Drop Pydantic's auto-generated ``title`` keys to save tokens."""
    if isinstance(schema, dict):
        out: dict[str, Any] = {}
        for key, value in schema.items():  # pyright: ignore[reportUnknownVariableType]
            if key == "title" and isinstance(value, str):
                continue
            if key in ("properties", "$defs") and isinstance(value, dict):
                out[key] = {  # pyright: ignore[reportUnknownArgumentType]
                    k: compact_schema(v)
                    for k, v in value.items()  # pyright: ignore[reportUnknownVariableType]
                }
            else:
                out[str(key)] = compact_schema(value)  # pyright: ignore[reportUnknownArgumentType]
        return out
    if isinstance(schema, list):
        return [compact_schema(v) for v in schema]  # pyright: ignore[reportUnknownVariableType]
    return schema


def matches_any(name: str, patterns: Iterable[str]) -> bool:
    """True when ``name`` matches one of the glob ``patterns``.

    A pattern without a wildcard also matches everything below it, so
    ``cloud.instances`` covers ``cloud.instances.list``.
    """
    for pattern in patterns:
        p = pattern.strip()
        if not p:
            continue
        if fnmatch.fnmatchcase(name, p):
            return True
        if "*" not in p and (name == p or name.startswith(p + ".")):
            return True
    return False


def unmatched_patterns(names: Iterable[str], patterns: Iterable[str]) -> list[str]:
    """Patterns that match none of ``names`` (usually a typo)."""
    all_names = list(names)
    return [
        p
        for p in patterns
        if p.strip() and not any(matches_any(n, [p]) for n in all_names)
    ]


class Catalog:
    """All exposed SDK methods, with search and schema lookup."""

    def __init__(self, entries: list[ToolEntry]):
        self.entries = sorted(entries, key=lambda e: e.name)
        self.by_name: dict[str, ToolEntry] = {e.name: e for e in self.entries}
        self._aliases: dict[str, str] = {}
        for e in self.entries:
            self._aliases[e.tool_name] = e.name
        docs = [self._search_doc(e) for e in self.entries]
        self._index = BM25Index(docs)
        self._path_tokens = {e.name: set(tokenize(e.name)) for e in self.entries}
        self._group_names = self._compute_groups()
        self._modules: dict[str, list[ToolEntry]] = {}
        for e in self.entries:
            self._modules.setdefault(e.group, []).append(e)
        self._stubs: dict[str, Any] = {}
        self._verbs = {
            e.name.rsplit(".", 1)[-1].split("_")[0] for e in self.entries
        } - {"and"}

    @staticmethod
    def _search_doc(entry: ToolEntry) -> list[str]:
        # Path tokens are repeated so names outweigh long descriptions.
        path = tokenize(entry.name)
        return path * 3 + tokenize(entry.summary) * 2 + tokenize(entry.description)

    @classmethod
    def from_client(
        cls,
        client: Any,
        include: list[str] | None = None,
        exclude: list[str] | None = None,
    ) -> "Catalog":
        """Introspect ``client`` (a ``Gcore`` or ``AsyncGcore``) into a catalog."""
        entries: list[ToolEntry] = []
        for full_name, method in iter_sdk_methods(client):
            service = full_name.split(".", 1)[0]
            leaf = full_name.rsplit(".", 1)[-1]
            if service in EXCLUDED_SERVICES or leaf in EXCLUDED_METHODS:
                continue
            if include and not matches_any(full_name, include):
                continue
            if exclude and matches_any(full_name, exclude):
                continue
            parsed = parse_docstring(_docstring(method))
            summary = parsed.summary
            if summary and leaf.endswith(POLL_SUFFIX) and "poll" not in summary.lower():
                summary = f"{summary} Waits for the task to finish."
            entries.append(
                ToolEntry(
                    name=full_name,
                    access=classify(full_name),
                    summary=summary,
                    description=parsed.description or summary,
                    method=method,
                    arg_docs=parsed.args,
                )
            )
        _fill_missing_summaries(entries)
        return cls(entries)

    # ------------------------------------------------------------------ lookup

    def resolve(self, name: str) -> ToolEntry | None:
        """Find an entry by dotted name or by its direct-mode identifier."""
        key = name.strip()
        if key in self.by_name:
            return self.by_name[key]
        alias = self._aliases.get(key)
        return self.by_name.get(alias) if alias else None

    # ------------------------------------------------------- script modules

    @property
    def module_paths(self) -> frozenset[str]:
        """Resources with operations (``cloud.floating_ips``): script modules."""
        return frozenset(self._modules)

    @property
    def package_paths(self) -> frozenset[str]:
        """Every importable path, including parents (``cloud``, ``cloud.load_balancers``)."""
        return self._group_names

    def module_entries(self, path: str) -> list[ToolEntry]:
        return self._modules.get(path, [])

    def stub(self, path: str) -> Any:
        """Typed stub of the script module ``path`` (cached), see ``stubs``."""
        from .stubs import module_stub

        if path not in self._stubs:
            self._stubs[path] = module_stub(path, self.module_entries(path))
        return self._stubs[path]

    def suggest(self, name: str, limit: int = 5) -> list[str]:
        """Names similar to an unknown ``name`` ("did you mean").

        Combines spelling similarity with a search on the name's words, so a
        wrong resource name (``cloud.vms.list``) still finds the right tool.
        """
        close = difflib.get_close_matches(name, list(self.by_name), n=limit, cutoff=0.6)
        for hit in self.search(name.replace(".", " ").replace("_", " "), limit=limit):
            if hit["name"] not in close:
                close.append(hit["name"])
        return close[:limit]

    # ------------------------------------------------------------------ search

    def search(
        self,
        query: str,
        limit: int | None = None,
        access: str | None = None,
    ) -> list[dict[str, Any]]:
        """Rank entries for a natural-language or keyword ``query``.

        A query that is exactly a resource path (``cloud.instances``) or ends in
        ``*`` lists that resource instead of ranking: its own operations first
        (up to 50 by default, so ``list`` isn't cut off alphabetically), then
        its sub-resources'. Ranked searches return 10 by default.
        """
        q = query.strip()
        candidates = self.entries
        if access:
            candidates = [e for e in candidates if e.access.value == access]

        prefix = q.rstrip("*").rstrip(".")
        if prefix and " " not in q and (q.endswith("*") or prefix in self._group_names):
            return self._list_resource(prefix, candidates, limit)
        limit = max(1, min(int(limit or 10), 50))

        base = tokenize(normalize_phrases(q))
        tokens = expand_query(base)
        if not tokens:
            return []
        scores = self._index.scores(tokens)
        allowed = {id(e) for e in candidates}
        query_verbs = [t for t in base if t in self._verbs]
        expanded = set(tokens)
        # Each query word with its synonyms, computed once per search.
        synonyms = [{t, *expand_query([t])} for t in base]

        def rank(entry: ToolEntry, bm25: float) -> float:
            path = self._path_tokens[entry.name]
            # How many of the user's words (or their synonyms) name this path.
            coverage = sum(1 for words in synonyms if path & words)
            # Path words the user did not ask about (``interfaces`` in
            # cloud.instances.interfaces.list for "list instances").
            extra = len(path - expanded - {entry.service})
            verb = entry.name.rsplit(".", 1)[-1].split("_")[0]
            if query_verbs:
                verb_bonus = 4.0 if verb in query_verbs else 0.0
            else:
                verb_bonus = 4.0 if verb == "list" else 0.0
            # Prefer plain methods over their *_and_poll twins, and shallow
            # (core) resources over deeply nested ones, on ties.
            poll_penalty = 0.5 if entry.name.endswith(POLL_SUFFIX) else 0.0
            depth_penalty = 0.3 * entry.name.count(".")
            return (
                coverage * 10
                + verb_bonus
                + 0.3 * bm25
                - 2.0 * extra
                - poll_penalty
                - depth_penalty
            )

        ranked = sorted(
            (
                (rank(e, s), e)
                for s, e in zip(scores, self.entries)
                if s > 0 and id(e) in allowed
            ),
            key=lambda t: (-t[0], len(t[1].name)),
        )
        return [self.brief(e) for _, e in ranked[:limit]]

    def _list_resource(
        self, prefix: str, candidates: list[ToolEntry], limit: int | None
    ) -> list[dict[str, Any]]:
        hits = [e for e in candidates if e.name.startswith(prefix + ".")]
        own = [e for e in hits if e.group == prefix]
        nested = [e for e in hits if e.group != prefix]
        if not own:
            # A service or package (``cloud``): its resources, not 50
            # arbitrary operations.
            depth = prefix.count(".") + 1
            counts: dict[str, int] = {}
            for e in nested:
                child = ".".join(e.name.split(".")[: depth + 1])
                counts[child] = counts.get(child, 0) + 1
            return [
                {"resource": child, "operations": count}
                for child, count in sorted(counts.items())
            ]
        n = max(1, min(int(limit or 50), 50))
        shown = (own + nested)[:n]
        out = [self.brief(e) for e in shown]
        if len(hits) > n:
            hidden = sorted({e.group for e in hits[n:] if e in nested} - {prefix})
            out.append(
                {
                    "more": f"{len(hits) - n} more operations; list a sub-resource "
                    "by its path to see them.",
                    "sub_resources": hidden,
                }
            )
        return out

    def _compute_groups(self) -> frozenset[str]:
        """Every resource path prefix (``cloud``, ``cloud.instances``, ...)."""
        groups: set[str] = set()
        for e in self.entries:
            parts = e.name.split(".")
            for i in range(1, len(parts)):
                groups.add(".".join(parts[:i]))
        return frozenset(groups)

    @staticmethod
    def brief(entry: ToolEntry) -> dict[str, Any]:
        """Compact search-result view of an entry."""
        out: dict[str, Any] = {"name": entry.name, "summary": entry.summary}
        if entry.access is not Access.READ:
            out["access"] = entry.access.value
        return out

    def describe(self, entry: ToolEntry) -> dict[str, Any]:
        """Full view of an entry: description, argument schema, result fields."""
        out: dict[str, Any] = {
            "name": entry.name,
            "access": entry.access.value,
            "description": entry.description,
            "input_schema": entry.input_schema,
        }
        if entry.returns:
            out["returns"] = {**entry.returns, "note": NULL_NOTE}
        return out

    def services(self) -> dict[str, int]:
        """Number of methods per top-level service."""
        counts: dict[str, int] = {}
        for e in self.entries:
            counts[e.service] = counts.get(e.service, 0) + 1
        return counts

    def snapshot(self) -> dict[str, Any]:
        """Stable, reviewable summary of the catalog for the golden file."""
        return {
            e.name: {"access": e.access.value, "required": e.required_params}
            for e in self.entries
        }


def _docstring(method: Callable[..., Any]) -> str | None:
    """The method's docstring, or its first overload's.

    Overloaded SDK methods (``cdn.origin_groups.create``) document each
    overload; the implementation itself has no docstring.
    """
    doc = getattr(method, "__doc__", None)
    if doc and doc.strip():
        return doc
    try:
        overloads = typing.get_overloads(getattr(method, "__func__", method))
    except Exception:
        return doc
    return next((o.__doc__ for o in overloads if o.__doc__), doc)


_POLL_PHRASE = re.compile(r"\s+and poll for the result", re.IGNORECASE)


def _fill_missing_summaries(entries: list[ToolEntry]) -> None:
    """Summaries for methods the SDK left undocumented.

    Borrow from the ``*_and_poll`` twin when it is documented (and the other
    way round), otherwise say what the name says, in words.
    """
    by_name = {e.name: e for e in entries}
    for entry in entries:
        if entry.summary:
            continue
        if entry.name.endswith(POLL_SUFFIX):
            twin = by_name.get(entry.name.removesuffix(POLL_SUFFIX))
            if twin and twin.summary:
                entry.summary = (
                    f"{twin.summary.rstrip('.')}. Waits for the task to finish."
                )
        else:
            twin = by_name.get(entry.name + POLL_SUFFIX)
            if twin and twin.summary and _POLL_PHRASE.search(twin.summary):
                entry.summary = _POLL_PHRASE.sub("", twin.summary)
        if not entry.summary:
            verb = entry.name.rsplit(".", 1)[-1].removesuffix(POLL_SUFFIX)
            resource = entry.group.rsplit(".", 1)[-1].replace("_", " ")
            entry.summary = f"{verb.replace('_', ' ').capitalize()} {resource}" + (
                " and wait for the task to finish."
                if entry.name.endswith(POLL_SUFFIX)
                else "."
            )
        if not entry.description:
            entry.description = entry.summary
